import { test, expect } from '@playwright/test';

test.describe('JavaScript Alert Confirmation Dialog', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/javascript_alerts');
  });

  test('should display confirm dialog and record user choice', async ({ page }) => {
    // Locate the button using getByRole
    const confirmButton = page.getByRole('button', { name: /click for js confirm/i });
    await expect(confirmButton).toBeVisible();

    // Click the confirm button to open the dialog
    await confirmButton.click();

    // Wait for the confirm dialog to appear
    const confirmDialog = page.locator('[data-testid="confirm-dialog"]');
    await expect(confirmDialog).toBeVisible();

    // Verify the dialog contains the correct message
    const confirmMessage = page.getByText('Are you sure you want to proceed?');
    await expect(confirmMessage).toBeVisible();

    // Verify the confirm button is visible
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    await expect(confirmButton).toBeVisible();

    // Verify the cancel button is visible
    const cancelButton = page.getByRole('button', { name: /cancel/i });
    await expect(cancelButton).toBeVisible();

    // Verify the result element is hidden by default
    const resultElement = page.getByText('You clicked:');
    await expect(resultElement).not.toBeVisible();

    // Click the confirm button
    await confirmButton.click();

    // Verify the result element shows 'You clicked: Ok'
    await expect(resultElement).toContainText('You clicked: Ok');

    // Verify the dialog is closed
    await expect(confirmDialog).not.toBeVisible();
  });

  test('should handle dismissing the dialog on a second attempt', async ({ page }) => {
    // Locate the confirm button using getByRole
    const confirmButton = page.getByRole('button', { name: /click for js confirm/i });
    await expect(confirmButton).toBeVisible();

    // Click the confirm button to open the dialog
    await confirmButton.click();

    // Wait for the confirm dialog to appear
    const confirmDialog = page.locator('[data-testid="confirm-dialog"]');
    await expect(confirmDialog).toBeVisible();

    // Verify the confirm button is visible
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    await expect(confirmButton).toBeVisible();

    // Verify the cancel button is visible
    const cancelButton = page.getByRole('button', { name: /cancel/i });
    await expect(cancelButton).toBeVisible();

    // Verify the result element is hidden by default
    const resultElement = page.getByText('You clicked:');
    await expect(resultElement).not.toBeVisible();

    // Click the confirm button
    await confirmButton.click();

    // Verify the result element shows 'You clicked: Ok'
    await expect(resultElement).toContainText('You clicked: Ok');

    // Click the confirm button again to dismiss the dialog
    await confirmButton.click();

    // Verify the result element shows 'You clicked: Cancel'
    await expect(resultElement).toContainText('You clicked: Cancel');

    // Verify the dialog is closed
    await expect(confirmDialog).not.toBeVisible();
  });
});
